// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;
    function setUp() public {
        admin = address(this);
        c = new Owned();
        vm.assume(msg.sender != admin);
    }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != admin);
        vm.assume(caller != address(0));
        address prevOwner = c.owner();
        vm.prank(caller);
        try c.setOwner(newOwner) {} catch {}
        bool ownerUnchanged = (c.owner() == prevOwner);
        assertTrue(ownerUnchanged);
    }
}
